//! Pure-Rust reimplementation of the mapbox `earcut.hpp` polygon
//! triangulation algorithm (ear clipping with z-order curve hashing),
//! ported behavior-for-behavior so that the produced triangle indices
//! match the C++ library byte-for-byte.
//!
//! Nodes live in an arena (`Vec<Node>`) and are referenced by index;
//! `remove_node` only unlinks, mirroring the C++ object pool.

pub type Point = [f64; 2];

struct Node {
    i: u32,
    x: f64,
    y: f64,
    prev: usize,
    next: usize,
    z: i32,
    prev_z: Option<usize>,
    next_z: Option<usize>,
    steiner: bool,
}

pub struct Earcut {
    nodes: Vec<Node>,
    pub indices: Vec<u32>,
    vertices: u32,
    hashing: bool,
    min_x: f64,
    max_x: f64,
    min_y: f64,
    max_y: f64,
    inv_size: f64,
}

impl Earcut {
    pub fn new() -> Self {
        Earcut {
            nodes: Vec::new(),
            indices: Vec::new(),
            vertices: 0,
            hashing: false,
            min_x: 0.0,
            max_x: 0.0,
            min_y: 0.0,
            max_y: 0.0,
            inv_size: 0.0,
        }
    }

    /// Triangulate a polygon given as a list of rings (outer ring first).
    /// Only the outer ring is used by this test program.
    pub fn run(&mut self, points: &[Vec<Point>]) {
        self.indices.clear();
        self.vertices = 0;

        if points.is_empty() {
            return;
        }

        let mut threshold: i64 = 80;
        let mut len: usize = 0;
        let mut i = 0usize;
        while threshold >= 0 && i < points.len() {
            threshold -= points[i].len() as i64;
            len += points[i].len();
            i += 1;
        }
        let _ = len;

        let outer_node = match self.linked_list(&points[0], true) {
            Some(node) => node,
            None => return,
        };
        if self.nodes[outer_node].prev == self.nodes[outer_node].next {
            return;
        }

        // if the shape is not too simple, we'll use z-order curve hash later
        self.hashing = threshold < 0;
        if self.hashing {
            let mut p = self.nodes[outer_node].next;
            let mut min_x = self.nodes[outer_node].x;
            let mut min_y = self.nodes[outer_node].y;
            let mut max_x = self.nodes[outer_node].x;
            let mut max_y = self.nodes[outer_node].y;
            loop {
                let x = self.nodes[p].x;
                let y = self.nodes[p].y;
                if x < min_x {
                    min_x = x;
                }
                if y < min_y {
                    min_y = y;
                }
                if x > max_x {
                    max_x = x;
                }
                if y > max_y {
                    max_y = y;
                }
                p = self.nodes[p].next;
                if p == outer_node {
                    break;
                }
            }
            self.min_x = min_x;
            self.min_y = min_y;
            self.max_x = max_x;
            self.max_y = max_y;
            self.inv_size = (max_x - min_x).max(max_y - min_y);
            self.inv_size = if self.inv_size != 0.0 {
                32767.0 / self.inv_size
            } else {
                0.0
            };
        }

        self.earcut_linked(outer_node, 0);
    }

    // create a circular doubly linked list from polygon points in the specified winding order
    fn linked_list(&mut self, points: &[Point], clockwise: bool) -> Option<usize> {
        let len = points.len();
        let mut sum = 0.0f64;
        let mut i = 0usize;
        let mut j = if len > 0 { len - 1 } else { 0 };
        while i < len {
            let p1 = points[i];
            let p2 = points[j];
            sum += (p2[0] - p1[0]) * (p1[1] + p2[1]);
            j = i;
            i += 1;
        }

        let mut last: Option<usize> = None;
        if clockwise == (sum > 0.0) {
            for k in 0..len {
                last = Some(self.insert_node(
                    self.vertices + k as u32,
                    points[k][0],
                    points[k][1],
                    last,
                ));
            }
        } else {
            let mut k = len;
            while k > 0 {
                k -= 1;
                last = Some(self.insert_node(
                    self.vertices + k as u32,
                    points[k][0],
                    points[k][1],
                    last,
                ));
            }
        }

        if let Some(l) = last {
            let ln = self.nodes[l].next;
            if self.equals(l, ln) {
                self.remove_node(l);
                last = Some(self.nodes[l].next);
            }
        }

        self.vertices += len as u32;

        last
    }

    // eliminate colinear or duplicate points
    fn filter_points(&mut self, start: usize, end: Option<usize>) -> usize {
        let mut end = end.unwrap_or(start);
        let mut p = start;
        loop {
            let mut again = false;

            let pn = self.nodes[p].next;
            let pp = self.nodes[p].prev;
            if !self.nodes[p].steiner
                && (self.equals(p, pn) || self.area(pp, p, pn) == 0.0)
            {
                self.remove_node(p);
                p = pp;
                end = p;

                if p == self.nodes[p].next {
                    break;
                }
                again = true;
            } else {
                p = self.nodes[p].next;
            }

            if !(again || p != end) {
                break;
            }
        }
        end
    }

    // main ear slicing loop which triangulates a polygon (given as a linked list)
    fn earcut_linked(&mut self, ear: usize, pass: i32) {
        // interlink polygon nodes in z-order
        if pass == 0 && self.hashing {
            self.index_curve(ear);
        }

        let mut ear = ear;
        let mut stop = ear;

        // iterate through ears, slicing them one by one
        while self.nodes[ear].prev != self.nodes[ear].next {
            let prev = self.nodes[ear].prev;
            let next = self.nodes[ear].next;

            let is_ear = if self.hashing {
                self.is_ear_hashed(ear)
            } else {
                self.is_ear(ear)
            };

            if is_ear {
                // cut off the triangle
                self.indices.push(self.nodes[prev].i);
                self.indices.push(self.nodes[ear].i);
                self.indices.push(self.nodes[next].i);

                self.remove_node(ear);

                // skipping the next vertex leads to less sliver triangles
                ear = self.nodes[next].next;
                stop = self.nodes[next].next;

                continue;
            }

            ear = next;

            // if we looped through the whole remaining polygon and can't find any more ears
            if ear == stop {
                if pass == 0 {
                    // try filtering points and slicing again
                    let f = self.filter_points(ear, None);
                    self.earcut_linked(f, 1);
                } else if pass == 1 {
                    // try curing all small self-intersections locally
                    let f = self.filter_points(ear, None);
                    let cured = self.cure_local_intersections(f);
                    self.earcut_linked(cured, 2);
                } else if pass == 2 {
                    // as a last resort, try splitting the remaining polygon into two
                    self.split_earcut(ear);
                }
                break;
            }
        }
    }

    // check whether a polygon node forms a valid ear with adjacent nodes
    fn is_ear(&self, ear: usize) -> bool {
        let a = self.nodes[ear].prev;
        let b = ear;
        let c = self.nodes[ear].next;

        if self.area(a, b, c) >= 0.0 {
            return false; // reflex, can't be an ear
        }

        let (ax, ay) = (self.nodes[a].x, self.nodes[a].y);
        let (bx, by) = (self.nodes[b].x, self.nodes[b].y);
        let (cx, cy) = (self.nodes[c].x, self.nodes[c].y);

        // now make sure we don't have other points inside the potential ear
        let mut p = self.nodes[self.nodes[ear].next].next;
        while p != self.nodes[ear].prev {
            if self.point_in_triangle(ax, ay, bx, by, cx, cy, self.nodes[p].x, self.nodes[p].y)
                && self.area(self.nodes[p].prev, p, self.nodes[p].next) >= 0.0
            {
                return false;
            }
            p = self.nodes[p].next;
        }

        true
    }

    fn is_ear_hashed(&self, ear: usize) -> bool {
        let a = self.nodes[ear].prev;
        let b = ear;
        let c = self.nodes[ear].next;

        if self.area(a, b, c) >= 0.0 {
            return false; // reflex, can't be an ear
        }

        let (ax, ay) = (self.nodes[a].x, self.nodes[a].y);
        let (bx, by) = (self.nodes[b].x, self.nodes[b].y);
        let (cx, cy) = (self.nodes[c].x, self.nodes[c].y);

        // triangle bbox; min & max are calculated like this for speed
        let min_tx = ax.min(bx).min(cx);
        let min_ty = ay.min(by).min(cy);
        let max_tx = ax.max(bx).max(cx);
        let max_ty = ay.max(by).max(cy);

        // z-order range for the current triangle bbox
        let min_z = self.z_order(min_tx, min_ty);
        let max_z = self.z_order(max_tx, max_ty);

        // first look for points inside the triangle in increasing z-order
        let mut p = self.nodes[ear].next_z;
        while let Some(pi) = p {
            if self.nodes[pi].z > max_z {
                break;
            }
            if pi != self.nodes[ear].prev
                && pi != self.nodes[ear].next
                && self.point_in_triangle(
                    ax,
                    ay,
                    bx,
                    by,
                    cx,
                    cy,
                    self.nodes[pi].x,
                    self.nodes[pi].y,
                )
                && self.area(self.nodes[pi].prev, pi, self.nodes[pi].next) >= 0.0
            {
                return false;
            }
            p = self.nodes[pi].next_z;
        }

        // then look for points in decreasing z-order
        let mut p = self.nodes[ear].prev_z;
        while let Some(pi) = p {
            if self.nodes[pi].z < min_z {
                break;
            }
            if pi != self.nodes[ear].prev
                && pi != self.nodes[ear].next
                && self.point_in_triangle(
                    ax,
                    ay,
                    bx,
                    by,
                    cx,
                    cy,
                    self.nodes[pi].x,
                    self.nodes[pi].y,
                )
                && self.area(self.nodes[pi].prev, pi, self.nodes[pi].next) >= 0.0
            {
                return false;
            }
            p = self.nodes[pi].prev_z;
        }

        true
    }

    // go through all polygon nodes and cure small local self-intersections
    fn cure_local_intersections(&mut self, start: usize) -> usize {
        let mut start = start;
        let mut p = start;
        loop {
            let a = self.nodes[p].prev;
            let pn = self.nodes[p].next;
            let b = self.nodes[pn].next;

            // a self-intersection where edge (a,p) intersects (p,b); remove p if possible
            if !self.equals(a, b)
                && self.intersects(a, p, pn, b)
                && self.locally_inside(a, b)
                && self.locally_inside(b, a)
            {
                self.indices.push(self.nodes[a].i);
                self.indices.push(self.nodes[p].i);
                self.indices.push(self.nodes[b].i);

                // remove two nodes involved
                self.remove_node(p);
                self.remove_node(pn);

                p = b;
                start = b;
            }
            p = self.nodes[p].next;
            if p == start {
                break;
            }
        }
        self.filter_points(p, None)
    }

    // try splitting polygon into two and triangulate them independently
    fn split_earcut(&mut self, start: usize) {
        // look for a valid diagonal that divides the polygon into two
        let mut a = start;
        loop {
            let mut b = self.nodes[self.nodes[a].next].next;
            while b != self.nodes[a].prev {
                if self.nodes[a].i != self.nodes[b].i && self.is_valid_diagonal(a, b) {
                    // split the polygon in two by the diagonal
                    let mut c = self.split_polygon(a, b);

                    // filter colinear points around the cuts
                    let an = self.nodes[a].next;
                    let a = self.filter_points(a, Some(an));
                    let cn = self.nodes[c].next;
                    c = self.filter_points(c, Some(cn));

                    // run earcut on each half
                    self.earcut_linked(a, 0);
                    self.earcut_linked(c, 0);
                    return;
                }
                b = self.nodes[b].next;
            }
            a = self.nodes[a].next;
            if a == start {
                break;
            }
        }
    }

    // interlink polygon nodes in z-order
    fn index_curve(&mut self, start: usize) {
        let mut p = start;
        loop {
            if self.nodes[p].z == 0 {
                let (x, y) = (self.nodes[p].x, self.nodes[p].y);
                self.nodes[p].z = self.z_order(x, y);
            }
            self.nodes[p].prev_z = Some(self.nodes[p].prev);
            self.nodes[p].next_z = Some(self.nodes[p].next);
            p = self.nodes[p].next;
            if p == start {
                break;
            }
        }

        let prev_z = self.nodes[p].prev_z.unwrap();
        self.nodes[prev_z].next_z = None;
        self.nodes[p].prev_z = None;

        self.sort_linked(p);
    }

    // Simon Tatham's linked list merge sort algorithm
    fn sort_linked(&mut self, start: usize) -> usize {
        let mut in_size = 1usize;
        let mut list = start;

        loop {
            let mut p: Option<usize> = Some(list);
            let mut new_list: Option<usize> = None;
            let mut tail: Option<usize> = None;
            let mut num_merges = 0;

            while let Some(p_head) = p {
                num_merges += 1;
                let mut q: Option<usize> = Some(p_head);
                let mut p_size = 0usize;
                for _ in 0..in_size {
                    p_size += 1;
                    q = self.nodes[q.unwrap()].next_z;
                    if q.is_none() {
                        break;
                    }
                }

                let mut q_size = in_size;
                let mut p_opt: Option<usize> = Some(p_head);

                while p_size > 0 || (q_size > 0 && q.is_some()) {
                    let e;
                    if p_size == 0 {
                        e = q.unwrap();
                        q = self.nodes[e].next_z;
                        q_size -= 1;
                    } else if q_size == 0 || q.is_none() {
                        e = p_opt.unwrap();
                        p_opt = self.nodes[e].next_z;
                        p_size -= 1;
                    } else if self.nodes[p_opt.unwrap()].z <= self.nodes[q.unwrap()].z {
                        e = p_opt.unwrap();
                        p_opt = self.nodes[e].next_z;
                        p_size -= 1;
                    } else {
                        e = q.unwrap();
                        q = self.nodes[e].next_z;
                        q_size -= 1;
                    }

                    match tail {
                        Some(t) => self.nodes[t].next_z = Some(e),
                        None => new_list = Some(e),
                    }
                    self.nodes[e].prev_z = tail;
                    tail = Some(e);
                }

                p = q;
            }

            self.nodes[tail.unwrap()].next_z = None;

            if num_merges <= 1 {
                return new_list.unwrap();
            }
            list = new_list.unwrap();
            in_size *= 2;
        }
    }

    // z-order of a point given coords and size of the data bounding box
    fn z_order(&self, x_: f64, y_: f64) -> i32 {
        // coords are transformed into non-negative 15-bit integer range
        let mut x = ((x_ - self.min_x) * self.inv_size) as i32;
        let mut y = ((y_ - self.min_y) * self.inv_size) as i32;

        x = (x | (x << 8)) & 0x00FF00FF;
        x = (x | (x << 4)) & 0x0F0F0F0F;
        x = (x | (x << 2)) & 0x33333333;
        x = (x | (x << 1)) & 0x55555555;

        y = (y | (y << 8)) & 0x00FF00FF;
        y = (y | (y << 4)) & 0x0F0F0F0F;
        y = (y | (y << 2)) & 0x33333333;
        y = (y | (y << 1)) & 0x55555555;

        x | (y << 1)
    }

    #[allow(clippy::too_many_arguments)]
    fn point_in_triangle(
        &self,
        ax: f64,
        ay: f64,
        bx: f64,
        by: f64,
        cx: f64,
        cy: f64,
        px: f64,
        py: f64,
    ) -> bool {
        (cx - px) * (ay - py) >= (ax - px) * (cy - py)
            && (ax - px) * (by - py) >= (bx - px) * (ay - py)
            && (bx - px) * (cy - py) >= (cx - px) * (by - py)
    }

    // check if a diagonal between two polygon nodes is valid (lies in polygon interior)
    fn is_valid_diagonal(&self, a: usize, b: usize) -> bool {
        let an = self.nodes[a].next;
        let ap = self.nodes[a].prev;
        let bp = self.nodes[b].prev;
        let bn = self.nodes[b].next;

        self.nodes[an].i != self.nodes[b].i
            && self.nodes[ap].i != self.nodes[b].i
            && !self.intersects_polygon(a, b) // doesn't intersect other edges
            && ((self.locally_inside(a, b)
                && self.locally_inside(b, a)
                && self.middle_inside(a, b)
                && (self.area(ap, a, bp) != 0.0 || self.area(a, bp, b) != 0.0))
                || (self.equals(a, b)
                    && self.area(ap, a, an) != 0.0
                    && self.area(bp, b, bn) != 0.0))
    }

    // signed area of a triangle
    fn area(&self, p: usize, q: usize, r: usize) -> f64 {
        (self.nodes[q].y - self.nodes[p].y) * (self.nodes[r].x - self.nodes[q].x)
            - (self.nodes[q].x - self.nodes[p].x) * (self.nodes[r].y - self.nodes[q].y)
    }

    // check if two points are equal
    fn equals(&self, p1: usize, p2: usize) -> bool {
        self.nodes[p1].x == self.nodes[p2].x && self.nodes[p1].y == self.nodes[p2].y
    }

    // check if two segments intersect
    fn intersects(&self, p1: usize, q1: usize, p2: usize, q2: usize) -> bool {
        if (self.equals(p1, q1) && self.equals(p2, q2))
            || (self.equals(p1, q2) && self.equals(p2, q1))
        {
            return true;
        }
        (self.area(p1, q1, p2) > 0.0) != (self.area(p1, q1, q2) > 0.0)
            && (self.area(p2, q2, p1) > 0.0) != (self.area(p2, q2, q1) > 0.0)
    }

    // check if a polygon diagonal intersects any polygon segments
    fn intersects_polygon(&self, a: usize, b: usize) -> bool {
        let mut p = a;
        loop {
            let pn = self.nodes[p].next;
            if self.nodes[p].i != self.nodes[a].i
                && self.nodes[pn].i != self.nodes[a].i
                && self.nodes[p].i != self.nodes[b].i
                && self.nodes[pn].i != self.nodes[b].i
                && self.intersects(p, pn, a, b)
            {
                return true;
            }
            p = pn;
            if p == a {
                break;
            }
        }
        false
    }

    // check if a polygon diagonal is locally inside the polygon
    fn locally_inside(&self, a: usize, b: usize) -> bool {
        let ap = self.nodes[a].prev;
        let an = self.nodes[a].next;
        if self.area(ap, a, an) < 0.0 {
            self.area(a, b, an) >= 0.0 && self.area(a, ap, b) >= 0.0
        } else {
            self.area(a, b, ap) < 0.0 || self.area(a, an, b) < 0.0
        }
    }

    // check if the middle point of a polygon diagonal is inside the polygon
    fn middle_inside(&self, a: usize, b: usize) -> bool {
        let mut p = a;
        let mut inside = false;
        let px = (self.nodes[a].x + self.nodes[b].x) / 2.0;
        let py = (self.nodes[a].y + self.nodes[b].y) / 2.0;
        loop {
            let pn = self.nodes[p].next;
            let p_x = self.nodes[p].x;
            let p_y = self.nodes[p].y;
            let pn_x = self.nodes[pn].x;
            let pn_y = self.nodes[pn].y;
            if ((p_y > py) != (pn_y > py))
                && pn_y != p_y
                && (px < (pn_x - p_x) * (py - p_y) / (pn_y - p_y) + p_x)
            {
                inside = !inside;
            }
            p = pn;
            if p == a {
                break;
            }
        }
        inside
    }

    // link two polygon vertices with a bridge;
    // if the vertices belong to the same ring, it splits the polygon into two
    fn split_polygon(&mut self, a: usize, b: usize) -> usize {
        let a2 = self.new_node(self.nodes[a].i, self.nodes[a].x, self.nodes[a].y);
        let b2 = self.new_node(self.nodes[b].i, self.nodes[b].x, self.nodes[b].y);
        let an = self.nodes[a].next;
        let bp = self.nodes[b].prev;

        self.nodes[a].next = b;
        self.nodes[b].prev = a;

        self.nodes[a2].next = an;
        self.nodes[an].prev = a2;

        self.nodes[b2].next = a2;
        self.nodes[a2].prev = b2;

        self.nodes[bp].next = b2;
        self.nodes[b2].prev = bp;

        b2
    }

    fn new_node(&mut self, i: u32, x: f64, y: f64) -> usize {
        let idx = self.nodes.len();
        self.nodes.push(Node {
            i,
            x,
            y,
            prev: idx,
            next: idx,
            z: 0,
            prev_z: None,
            next_z: None,
            steiner: false,
        });
        idx
    }

    fn insert_node(&mut self, i: u32, x: f64, y: f64, last: Option<usize>) -> usize {
        let p = self.new_node(i, x, y);
        if let Some(l) = last {
            let ln = self.nodes[l].next;
            self.nodes[p].next = ln;
            self.nodes[p].prev = l;
            self.nodes[ln].prev = p;
            self.nodes[l].next = p;
        }
        p
    }

    fn remove_node(&mut self, p: usize) {
        let pn = self.nodes[p].next;
        let pp = self.nodes[p].prev;
        self.nodes[pn].prev = pp;
        self.nodes[pp].next = pn;

        if let Some(pz) = self.nodes[p].prev_z {
            self.nodes[pz].next_z = self.nodes[p].next_z;
        }
        if let Some(nz) = self.nodes[p].next_z {
            self.nodes[nz].prev_z = self.nodes[p].prev_z;
        }
    }
}

/// Convenience function matching `mapbox::earcut<uint32_t>(polygon)`.
pub fn earcut(polygon: &[Vec<Point>]) -> Vec<u32> {
    let mut e = Earcut::new();
    e.run(polygon);
    e.indices
}

