mod earcut;

use std::io::Write;

/// C `atoi` equivalent: skip leading whitespace, optional sign, decimal digits.
fn atoi(s: &str) -> i32 {
    let bytes = s.as_bytes();
    let mut idx = 0usize;
    while idx < bytes.len()
        && matches!(bytes[idx], b' ' | b'\t' | b'\n' | b'\x0B' | b'\x0C' | b'\r')
    {
        idx += 1;
    }
    let mut sign: i64 = 1;
    if idx < bytes.len() && (bytes[idx] == b'+' || bytes[idx] == b'-') {
        if bytes[idx] == b'-' {
            sign = -1;
        }
        idx += 1;
    }
    let mut val: i64 = 0;
    while idx < bytes.len() && bytes[idx].is_ascii_digit() {
        val = val.saturating_mul(10).saturating_add((bytes[idx] - b'0') as i64);
        idx += 1;
    }
    (sign * val) as i32
}

fn main() {
    let args: Vec<String> = std::env::args().collect();

    let mut n: i32 = 19;
    if args.len() > 1 {
        n = atoi(&args[1]);
    }

    let mut fractal: Vec<earcut::Point> = Vec::new();

    let mut i: i32 = 0;
    while i < n * 2 {
        let t = f64::from(i) / f64::from(n * 2);
        let x = t * 3.0;
        let y = (t * 10.0).sin() * (-t).exp() * 2.0 + 1.0;
        fractal.push([x, y]);
        i += 1;
    }

    fractal.push([3.0, 0.0]);
    fractal.push([0.0, 0.0]);

    let polygon = vec![fractal];

    let indices = earcut::earcut(&polygon);

    let stdout = std::io::stdout();
    let mut out = std::io::BufWriter::new(stdout.lock());
    for idx in indices {
        write!(out, "{} ", idx).unwrap();
    }
    out.flush().unwrap();
}

